 private final AccessibilityService service;private final Context context;private final float[] anchor;private final Dialog dialog;private final LinearLayout root,list;private final java.util.ArrayList<Dialog> children=new java.util.ArrayList<>();private replica.ColorMotion motion;private volatile boolean closed;private boolean loading;private volatile Process query,previewProcess;private volatile int previewGeneration;private final java.util.LinkedHashMap<Integer,ImageView> previewViews=new java.util.LinkedHashMap<>();private final java.util.ArrayList<android.graphics.Bitmap> previewBitmaps=new java.util.ArrayList<>();
